<template><article class="exchange-message" :class="tone" :data-message-kind="event?.kind||'context'"><header><span class="avatar">{{ initials }}</span><div><b>{{ name }}</b><small>{{ caption }}<template v-if="event"> · {{ event.reused?'Earlier · ':'' }}<time :datetime="event.at?(event.message?.recorded_at||new Date(event.at).toISOString()):undefined" :title="event.at?(event.message?.recorded_at||new Date(event.at).toLocaleString()):'Time not recorded'">{{ event.at?new Date(event.at).toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'Time not recorded' }}</time></template></small></div></header><div class="message-copy"><p>{{ full?text:excerpt }}</p><small v-if="!full&&text.length>180" class="excerpt-label">Excerpt from the recorded message</small><details v-if="!full&&text.length>180"><summary>Read original full message</summary><p>{{ text }}</p></details></div></article></template>
<script setup>
import {computed} from 'vue'
const props=defineProps({event:Object,name:String,caption:String,tone:{default:'question'},text:{default:''},full:Boolean})
const initials=computed(()=>props.name?.split(/\s+/).slice(0,2).map(s=>s[0]).join('')||'·')
const excerpt=computed(()=>props.text.length>180?props.text.slice(0,177).replace(/\s+\S*$/,'')+'…':props.text)
</script>
<style scoped>
.exchange-message{min-width:0}.exchange-message header{display:flex;gap:9px;align-items:start}.avatar{width:29px;height:29px;flex:0 0 29px;background:#fff0e5;color:#bd6c3d;border-radius:50%;display:grid;place-items:center;font-size:10px}.exchange-message b{display:block;font-size:12px;font-weight:550;color:#34465d;line-height:1.5}.exchange-message small{font-size:10px;color:#8493a6;line-height:1.6}.message-copy{margin:9px 0 0 38px;padding:13px 14px;background:#fff6ef;border:1px solid #f5e7dc;border-radius:0 9px 9px 9px;font-size:12px;line-height:1.75;color:#586c84;overflow-wrap:anywhere}.message-copy p{white-space:pre-wrap;margin:0}.message-copy details{margin-top:8px}.message-copy summary{font-size:11px;cursor:pointer;color:#a36a44}.message-copy details p{margin-top:10px}.reply .message-copy{background:#f3f8ff;border-color:#e1eaf7}.reply .avatar{background:#edf5ff;color:#4d84b8}.context .message-copy{background:#f8fafc;border-color:#e7edf4}.excerpt-label{display:block;margin-top:5px}@media(max-width:620px){.message-copy{margin-left:0}}

.message-copy{padding:9px 11px;margin:6px 0 0 34px;line-height:1.65}.exchange-message header{gap:7px}.avatar{width:26px;height:26px;flex-basis:26px}.exchange-message small{font-size:9px}.message-copy details{margin-top:5px}@media(max-width:620px){.message-copy{margin-left:0}}
</style>
